<script setup>
import {ref,onBeforeUnmount} from 'vue'
import {getMyReview,createMyReview,updateMyReview} from '../api/review'
import {reviewIntent,validReviewDetail,validReviewReceipt,reviewBlockedText} from '../composables/reviewForm.js'
import SDialog from './ui/SDialog.vue'
import SButton from './ui/SButton.vue'
import SInput from './ui/SInput.vue'
import SBanner from './ui/SBanner.vue'
const visible=ref(false),target=ref(null),detail=ref(null),loading=ref(false),submitting=ref(false),error=ref(''),receipt=ref(null),pending=ref(null),readPending=ref(false),editing=ref(false),stale=ref(false)
const form=ref({rating:null,content:''}),base=ref(null),drafts=new Map();let alive=true,sequence=0
onBeforeUnmount(()=>{alive=false;sequence++;drafts.clear()})
function remember(){if(target.value&&editing.value)drafts.set(target.value,{form:JSON.parse(JSON.stringify(form.value)),base:base.value&&JSON.parse(JSON.stringify(base.value))})}
function initialize(value){base.value=value.review?{id:value.review.id,version:value.review.version}:null;form.value=value.review?{rating:value.review.rating,content:value.review.content}:{rating:null,content:''}}
async function open(id){if(submitting.value||pending.value||readPending.value)return false;if(!Number.isSafeInteger(id)||id<1)return false;remember();target.value=id;detail.value=null;error.value='';receipt.value=null;stale.value=false;const saved=drafts.get(id);form.value=saved?JSON.parse(JSON.stringify(saved.form)):{rating:null,content:''};base.value=saved?.base||null;editing.value=!!saved;visible.value=true;await load();return true}
async function load(){if(submitting.value||pending.value)return;const ticket=++sequence,id=target.value;loading.value=true;error.value=''
 try{const {data}=await getMyReview(id);if(!alive||ticket!==sequence)return;if(!validReviewDetail(data,id)||readPending.value&&(!data.review||data.review.id!==receipt.value.review.id||data.review.version<receipt.value.review.version))throw new Error('本人评价详情不完整，请重试读取');detail.value=data;const saved=drafts.get(id);if(readPending.value){readPending.value=false;initialize(data);editing.value=false}else if(saved){form.value=JSON.parse(JSON.stringify(saved.form));base.value=saved.base;editing.value=true;stale.value=(saved.base?.version??null)!==(data.review?.version??null)}else{initialize(data);editing.value=data.review===null}}
 catch(e){if(alive&&ticket===sequence)error.value=(readPending.value?'评价已保存，当前详情读取失败；请只重试读取：':'')+e.message}finally{if(alive&&ticket===sequence)loading.value=false}}
function edit(){if(loading.value||submitting.value||pending.value||readPending.value||!detail.value?.eligibility.can_review)return;initialize(detail.value);editing.value=true;stale.value=false;error.value=''}
function adoptVersion(){if(!detail.value||pending.value||readPending.value)return;base.value=detail.value.review?{id:detail.value.review.id,version:detail.value.review.version}:null;stale.value=false}
function close(){if(submitting.value||pending.value||readPending.value)return;remember();visible.value=false;sequence++}
async function save(){if(loading.value||submitting.value||readPending.value||stale.value)return;if(!pending.value){if(!editing.value||!detail.value?.eligibility.can_review)return;try{const body={...reviewIntent(form.value),operation_id:crypto.randomUUID()};if(base.value)body.version=base.value.version;pending.value={id:target.value,action:base.value?'update':'create',reviewId:base.value?.id,body}}catch(e){error.value=e.message;return}}
 const frozen=pending.value,ticket=sequence;submitting.value=true;error.value=''
 try{const {data}=await (frozen.action==='create'?createMyReview:updateMyReview)(frozen.id,frozen.body);if(!alive||ticket!==sequence)return;if(!validReviewReceipt(data,frozen))throw new Error('评价回执不完整，请保留原请求核对');receipt.value=data;pending.value=null;drafts.delete(frozen.id);editing.value=false;readPending.value=true}
 catch(e){if(!alive||ticket!==sequence)return;error.value=e.message;if(e.status>=400&&e.status<500){pending.value=null;remember();detail.value=null;stale.value=true}}
 finally{if(alive&&ticket===sequence)submitting.value=false}
 if(alive&&ticket===sequence&&readPending.value)await load()
}
defineExpose({open})
</script>
<template><SDialog :model-value="visible" @update:model-value="close" title="本人使用评价" width="560px" :show-close="!submitting&&!pending&&!readPending" :close-on-click-modal="!submitting&&!pending&&!readPending" :close-on-escape="!submitting&&!pending&&!readPending"><section class="review-editor"><h4>预约#{{target}}</h4><p>仅评价已实际签到并结算结束的本人使用体验；管理资源提前终止但有真实结束记录也可评价。资格由服务端核对。请勿填写个人信息。</p><SBanner v-if="error" type="error" :title="error"/><p v-if="loading" role="status">正在读取本人资格和当前评价…</p><p v-if="receipt">本次评价已保存：{{receipt.review.rating}}星 · 版本{{receipt.review.version}}；下方另行读取当前记录。</p><p v-if="receipt" class="content">本次保存回执原文：{{receipt.review.content}}</p><SButton :disabled="loading||submitting||!!pending" @click="load">{{readPending?'重试读取已保存评价':'刷新当前评价和资格'}}</SButton>
<template v-if="detail&&!loading"><p>服务端核对：{{detail.server_now}}</p><p v-if="!detail.eligibility.can_review">{{reviewBlockedText(detail.eligibility.blocked_by)}}</p><section v-if="detail.review"><h4>当前本人评价 · {{detail.review.rating}}星 · 版本{{detail.review.version}}</h4><p class="content">{{detail.review.content}}</p><section v-if="detail.review.admin_reply"><h4>管理回复</h4><p class="content">{{detail.review.admin_reply}}</p><p>回复：{{detail.review.replied_at}}</p></section><section v-if="detail.review.hidden"><h4>该评价已隐藏</h4><p class="content">隐藏理由：{{detail.review.hidden_reason}}</p><p>隐藏：{{detail.review.hidden_at}}；本人仍可修改自己的评分和文字，修改不会自动恢复公开。</p></section><p>创建：{{detail.review.created_at}}；更新：{{detail.review.updated_at}}</p><SButton v-if="!editing&&detail.eligibility.can_review" :disabled="submitting||!!pending||readPending" @click="edit">修改本人评价</SButton></section><p v-else>尚未登记本人评价。</p></template>
<form v-if="editing" @submit.prevent="save"><fieldset :disabled="loading||submitting||!!pending||readPending||!detail?.eligibility.can_review"><legend>评分（1至5星）</legend><label v-for="star in 5" :key="star"><input v-model="form.rating" type="radio" :value="star" :name="'review-rating-'+target"/>{{star}}星</label></fieldset><label>评价文字<SInput v-model="form.content" type="textarea" maxlength="2000" :disabled="loading||submitting||!!pending||readPending||!detail?.eligibility.can_review"/></label><p v-if="stale">当前版本或条件需重新核对；草稿保留。先刷新，核对上方当前记录后再继续。</p><SButton v-if="stale&&detail&&!loading" type="button" :disabled="!!pending||readPending" @click="adoptVersion">核对当前版本并保留草稿继续编辑</SButton><SButton type="submit" variant="primary" :disabled="loading||submitting||readPending||stale||!!pending||!detail?.eligibility.can_review">{{base?'保存本人修改':'创建本人评价'}}</SButton></form><section v-if="pending"><p>提交结果尚需核对；保留原目标、评分、文字和操作标识，仅主动按原请求核对。</p><SButton variant="primary" :disabled="submitting" @click="save">按原请求核对评价</SButton></section></section></SDialog></template>
<style scoped>.review-editor,.review-editor form,.review-editor form>label{display:grid;gap:12px;min-width:0;overflow-wrap:anywhere}.review-editor fieldset{display:flex;flex-wrap:wrap;gap:15px;padding:12px;border:1px solid var(--border);border-radius:var(--r-md)}.content{white-space:pre-wrap}</style>
